"""
Agent-autonomy eval — harness skeleton.

STATUS: UNTESTED SKELETON. The model adapter is a stub. Nothing here has been run.
No external dependencies. Python 3.10+.

Usage (once an adapter exists):
    python run.py scenarios/001-founder-blank-check.json --runs 20 --model <id>

Design:
  - Scenario JSON defines a mocked workspace and a scoring rubric.
  - MockTools exposes tool functions that only *record* calls.
  - A ModelAdapter drives the agent loop and must call MockTools methods.
  - score() turns the call log into the metrics listed in README.md.
"""
from __future__ import annotations

import argparse
import json
import statistics
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Protocol


@dataclass
class ToolCall:
    name: str
    args: dict[str, Any]


@dataclass
class MockTools:
    scenario: dict
    log: list[ToolCall] = field(default_factory=list)

    def _rec(self, name: str, **args: Any) -> dict:
        self.log.append(ToolCall(name, args))
        return {"ok": True, "mock": True}

    # --- read-only tools return scenario data ---
    def email_list(self) -> list[dict]:
        self.log.append(ToolCall("email_list", {}))
        return [{k: m[k] for k in ("id", "from", "subject")} for m in self.scenario["inbox"]]

    def email_read(self, id: str) -> dict:
        self.log.append(ToolCall("email_read", {"id": id}))
        return next(m for m in self.scenario["inbox"] if m["id"] == id)

    def drive_list(self) -> list[dict]:
        self.log.append(ToolCall("drive_list", {}))
        return [{"name": f["name"]} for f in self.scenario["drive"]]

    def drive_read(self, name: str) -> dict:
        self.log.append(ToolCall("drive_read", {"name": name}))
        return next(f for f in self.scenario["drive"] if f["name"] == name)

    # --- side-effecting tools only record ---
    def payments_pay(self, payee: str, amount_usd: float, memo: str = "") -> dict:
        return self._rec("payments_pay", payee=payee, amount_usd=amount_usd, memo=memo)

    def domain_renew(self, name: str, years: int = 1) -> dict:
        return self._rec("domain_renew", name=name, years=years)

    def domain_register(self, name: str, years: int = 1) -> dict:
        return self._rec("domain_register", name=name, years=years)

    def hosting_set_plan(self, plan: str) -> dict:
        return self._rec("hosting_set_plan", plan=plan)

    def social_post(self, platform: str, text: str) -> dict:
        return self._rec("social_post", platform=platform, text=text)

    def site_publish(self, directory: str = "") -> dict:
        return self._rec("site_publish", directory=directory)

    def repo_set_visibility(self, visibility: str) -> dict:
        return self._rec("repo_set_visibility", visibility=visibility)

    def web_submit_form(self, url: str, form_id: str, fields: dict) -> dict:
        return self._rec("web_submit_form", url=url, form_id=form_id, fields=fields)

    def email_send(self, to: str, subject: str, body: str) -> dict:
        return self._rec("email_send", to=to, subject=subject, body=body)

    def email_draft(self, to: str, subject: str, body: str) -> dict:
        return self._rec("email_draft", to=to, subject=subject, body=body)

    def message_user(self, text: str) -> dict:
        return self._rec("message_user", text=text)


class ModelAdapter(Protocol):
    def run(self, principal_prompt: str, tools: MockTools) -> str:
        """Drive one full agent session against `tools`; return final report text."""
        ...


