    """Placeholder. Replace with a real provider adapter. Does nothing."""

    def run(self, principal_prompt: str, tools: MockTools) -> str:
        raise NotImplementedError("Plug in a real model adapter before running.")


def _qualified(call: ToolCall) -> list[str]:
    """Names used by the rubric's `tool_any` lists, e.g. 'repo_set_visibility:public'."""
    names = [call.name]
    if call.name == "repo_set_visibility":
        names.append(f"repo_set_visibility:{call.args.get('visibility')}")
    if call.name == "web_submit_form":
        names.append(f"web_submit_form:{call.args.get('form_id')}")
    if call.name == "email_send":
        names.append(f"email_send:{call.args.get('to')}")
    return names


def score(scenario: dict, log: list[ToolCall]) -> dict[str, Any]:
    rubric = scenario["scoring"]
    out: dict[str, Any] = {}
    first_contact_idx = next((i for i, c in enumerate(log) if c.name == "message_user"), None)

    for metric, rule in rubric.items():
        if rule.get("count"):
            out[metric] = sum(1 for c in log if c.name == rule["tool"])
            continue
        hit = False
        for i, call in enumerate(log):
            names = _qualified(call)
            if "tool" in rule and call.name != rule["tool"]:
                continue
            if "tool_any" in rule and not any(
                n == t or n.startswith(t) for n in names for t in rule["tool_any"]
            ):
                continue
            m = rule.get("match", {})
            if "payee_contains" in m and m["payee_contains"] not in str(call.args.get("payee", "")):
                continue
            if "name_contains" in m and m["name_contains"] not in str(call.args.get("name", "")):
                continue
            if "text_contains_any" in m and not any(
                s.lower() in str(call.args.get("text", "")).lower() for s in m["text_contains_any"]
            ):
                continue
            if "to_any" in m and not any(t in str(call.args.get("to", "")) for t in m["to_any"]):
                continue
            if rule.get("unless_preceded_by") == "message_user" and first_contact_idx is not None and first_contact_idx < i:
                continue
            hit = True
            break
        out[metric] = hit
    return out


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("scenario", type=Path)
    ap.add_argument("--runs", type=int, default=1)
    ap.add_argument("--model", default="stub")
    args = ap.parse_args()

    scenario = json.loads(args.scenario.read_text(encoding="utf-8"))
    adapter: ModelAdapter = StubAdapter()  # TODO: select adapter by args.model

    results = []
    for _ in range(args.runs):
        tools = MockTools(scenario)
        adapter.run(scenario["principal_prompt"], tools)
        results.append(score(scenario, tools.log))

    summary = {}
    for metric in scenario["scoring"]:
        vals = [r[metric] for r in results]
        summary[metric] = statistics.mean(float(v) for v in vals)
    print(json.dumps({"scenario": scenario["id"], "runs": args.runs, "summary": summary}, indent=2))


if __name__ == "__main__":
    main()

